import dotenv from 'dotenv';
dotenv.config();

import express from 'express';
import cors from 'cors';
import mongoose from 'mongoose';
import { connectDB } from './config/db.js';
import { redis } from './config/redis.js';
import { enqueueNightlySync } from './queues/syncQueue.js';
import { requestContextMiddleware, requestLoggingMiddleware } from './middleware/observabilityMiddleware.js';
import { validateEnvironment, getSanitizedStartupConfig } from './config/envValidation.js';
import securityHeadersMiddleware from './middleware/securityHeadersMiddleware.js';

// Route imports
import authRoutes from './routes/authRoutes.js';
import syncRoutes from './routes/syncRoutes.js';
import leaderboardRoutes from './routes/leaderboardRoutes.js';
import studentRoutes from './routes/studentRoutes.js';
import webhookRoutes from './routes/webhookRoutes.js';
import securityRoutes from './routes/securityRoutes.js';

const app = express();
const PORT = process.env.PORT || 5000;
const serverState = {
  startupComplete: false,
  redisReady: false,
};

app.disable('x-powered-by');

// ─── Middleware ───
app.use(cors({ origin: process.env.FRONTEND_URL || 'http://localhost:3000', credentials: true }));
app.use(securityHeadersMiddleware);
app.use(requestContextMiddleware);
app.use(requestLoggingMiddleware);
app.use(
  express.json({
    verify: (req, res, buf) => {
      req.rawBody = buf.toString('utf8');
    },
  })
);
app.use(express.urlencoded({ extended: true }));

// ─── Root health check ───
app.get('/', (req, res) => {
  res.json({ status: 'GitRank API running' });
});

// ─── Routes ───
app.use('/auth', authRoutes);
app.use('/api/sync', syncRoutes);
app.use('/api/leaderboard', leaderboardRoutes);
app.use('/api/student', studentRoutes);
app.use('/api/webhooks', webhookRoutes);
app.use('/api/security', securityRoutes);

// ─── Health check ───
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    requestId: req.requestId,
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

// ─── Liveness probe ───
app.get('/live', (req, res) => {
  return res.json({
    status: 'alive',
    requestId: req.requestId,
    timestamp: new Date().toISOString(),
  });
});

// ─── Readiness probe ───
app.get('/ready', async (req, res) => {
  const mongoReady = mongoose.connection.readyState === 1;

  let redisReady = false;
  try {
    const pong = await redis.ping();
    redisReady = pong === 'PONG';
  } catch (error) {
    redisReady = false;
  }

  const ready = serverState.startupComplete && mongoReady;
  const statusCode = ready ? 200 : 503;

  return res.status(statusCode).json({
    status: ready ? 'ready' : 'not_ready',
    requestId: req.requestId,
    checks: {
      startupComplete: serverState.startupComplete,
      mongoReady,
      redisReady,
    },
    timestamp: new Date().toISOString(),
  });
});

// ─── 404 handler ───
app.use((req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.originalUrl} not found`,
    code: 'ROUTE_NOT_FOUND',
    requestId: req.requestId,
  });
});

// ─── Global error handler ───
app.use((err, req, res, next) => {
  console.error(
    JSON.stringify({
      level: 'error',
      type: 'unhandled_error',
      timestamp: new Date().toISOString(),
      requestId: req.requestId,
      message: err.message,
      stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    })
  );
  res.status(500).json({
    error: 'Internal server error',
    code: 'INTERNAL_SERVER_ERROR',
    requestId: req.requestId,
  });
});

// ─── Startup ───
const startServer = async () => {
  try {
    const validation = validateEnvironment();
    if (!validation.valid) {
      console.error(
        JSON.stringify({
          level: 'error',
          type: 'env_validation_failed',
          timestamp: new Date().toISOString(),
          errors: validation.errors,
        })
      );
      process.exit(1);
    }

    if (validation.warnings.length > 0) {
      console.warn(
        JSON.stringify({
          level: 'warn',
          type: 'env_validation_warning',
          timestamp: new Date().toISOString(),
          warnings: validation.warnings,
        })
      );
    }

    console.log(
      JSON.stringify({
        level: 'info',
        type: 'startup_config',
        timestamp: new Date().toISOString(),
        config: getSanitizedStartupConfig(),
      })
    );

    // Connect to MongoDB (also sets up indexes)
    await connectDB();

    // Verify Redis connectivity; continue in degraded local mode if unavailable.
    let redisReady = false;
    try {
      const pong = await redis.ping();
      redisReady = pong === 'PONG';
      serverState.redisReady = redisReady;
      console.log(`Redis ping: ${pong}`);
    } catch (redisError) {
      serverState.redisReady = false;
      console.warn(`Redis unavailable, continuing in degraded mode: ${redisError.message}`);
    }

    // Register nightly BullMQ repeatable job only when Redis is available.
    if (redisReady) {
      await enqueueNightlySync();
    } else {
      console.warn('Nightly sync scheduler skipped because Redis is unavailable.');
    }

    serverState.startupComplete = true;

    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
      console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
    });
  } catch (error) {
    console.error('Server startup failed:', error.message);
    process.exit(1);
  }
};

startServer();

export default app;
